    "t13_text": "Megkülönböztetsz két magánhangzót ugyanabban a szótagban és két magánhangzót különböző szótagokban. Az elemzés szintjén dolgozol.",
    "t13_h1": "Az \"oa\" az \"ősz\" szóban diftongus.",
    "t13_h2": "\"po-et\" a szünet.",
    "t13_q": "Melyik példa a szünet?",
    "t13_qa": "talán",
    "t13_qb": "ősz",
    "t13_qc": "rossz este",
    "t13_qd": "ó, hajrá",
    "t14_title": "Egyszótagú, kéttagú, háromtagú (elemzési szint)",
    "t14_text": "Csoportosítsd a szavakat szótagszám szerint! Az elemzés szintjén dolgozol.",
    "t14_h1": "Számolja meg a hangszálakat.",
    "t14_h2": "Fa = egyszótag, gyermek = kéttagú.",
    "t14_q": "A \"notebook\" a következő:",
