    "t14_qd": "szótagok nélkül",
    "t15_title": "Szóhangsúly (elemzési szint)",
    "t15_text": "Határozza meg a hangsúlyos szótagot a gyakori példákban! Az elemzés szintjén dolgozol.",
    "t15_h1": "A hangsúlyos szótagot intenzívebben ejtik.",
    "t15_h2": "Az akcentus megváltoztathatja a beszéd tisztaságát.",
