    "t2_title": "Személy és szám (alapszint)",
    "t2_text": "Ön határozza meg az igealakok személyét és számát. Alapszinten dolgozol.",
    "t2_h1": "Az ige az alanyt tükrözi.",
    "t2_h2": "A befejezés megadja a támpontot.",
